package pilots;
import java.io.*;import javax.microedition.media.*;
public class PackedMediaTest{public static void main(String[] args)throws Exception{BufferedReader list=new BufferedReader(new FileReader(args[0]));int clips=0;long start=System.nanoTime();String line;while((line=list.readLine())!=null){String[] fields=line.split(",");InputStream input=PackedResources.open("/"+fields[0]);Player player=Manager.createPlayer(input,"audio/x-wav");player.realize();player.prefetch();player.start();Manager.FakePlayer fake=(Manager.FakePlayer)player;int expected=Integer.parseInt(fields[1])*2+44;if(fake.data.length!=expected)throw new Exception("Duration "+line);if(expected<=32768){int hits=PackedResources.waveCacheHits;DataInputStream replay=new DataInputStream(PackedResources.open("/"+fields[0]));byte[] again=new byte[expected];replay.readFully(again);if(replay.read()!=-1)throw new Exception("Replay length");replay.close();if(!java.util.Arrays.equals(fake.data,again)||PackedResources.waveCacheHits!=hits+1)throw new Exception("PCM cache mismatch "+line);}player.stop();player.close();input.close();Manager.players.clear();clips++;}System.out.println("MMAPI spy valid PCM11025/16: clips="+clips+" cache_hits="+PackedResources.waveCacheHits+" ms="+(System.nanoTime()-start)/1000000);}}
